import {useEffect,useState} from 'react';import api,{message} from '../services/api.js';
export default function Settings(){const [form,setForm]=useState({libraryName:'My Library',loanDays:'14',finePerDay:'10',maxBooks:'3'}),[saved,setSaved]=useState(false),[error,setError]=useState('');useEffect(()=>{api.get('/settings').then(r=>setForm(x=>({...x,...r.data}))).catch(e=>setError(message(e)))},[]);async function save(e){e.preventDefault();try{await api.put('/settings',form);setSaved(true);setTimeout(()=>setSaved(false),1800)}catch(e){setError(message(e))}}async function backup(){try{const r=await api.get('/backup');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(r.data,null,2)],{type:'application/json'}));a.download=`library-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)}catch(e){setError(message(e))}}return <><div className="page-head"><div><h2>Settings</h2><p>Configure circulation rules for the library.</p></div><button className="btn" onClick={backup}>Download backup</button></div>{error&&<div className="alert error">{error}</div>}{saved&&<div className="alert success-alert">Settings saved.</div>}<div className="panel settings"><form onSubmit={save} className="form-grid"><label>Library name<input value={form.libraryName} onChange={e=>setForm({...form,libraryName:e.target.value})}/></label><label>Loan period (days)<input type="number" min="1" value={form.loanDays} onChange={e=>setForm({...form,loanDays:e.target.value})}/></label><label>Fine per overdue day<input type="number" min="0" value={form.finePerDay} onChange={e=>setForm({...form,finePerDay:e.target.value})}/></label><label>Default member limit<input type="number" min="1" value={form.maxBooks} onChange={e=>setForm({...form,maxBooks:e.target.value})}/></label><div className="full-col"><button className="btn primary">Save settings</button></div></form></div></>}
